head.b:skin:
/* =========================================================
   Template : Dendam Sunyi - Personal Writing Blog (versi ringan + SEO)
   Kanvas   : 980px, responsive, soft grey gradient
   ========================================================= */
*{box-sizing:border-box}
body{margin:0;font:15px/1.75 'Inter',system-ui,sans-serif;color:#2f3237;
  background:linear-gradient(160deg,#f2f3f4 0%,#e0e2e5 45%,#c9cdd3 100%) fixed}
a{color:inherit;text-decoration:none}
img{max-width:100%}
.section,.widget{margin:0;padding:0}

/* Kanvas 980 x 900 */
.canvas{position:relative;width:100%;max-width:980px;min-height:900px;margin:24px auto;
  background:rgba(255,255,255,.75);border-radius:18px;overflow:hidden;
  box-shadow:0 20px 60px rgba(60,66,77,.14)}
@media(max-width:1020px){.canvas{margin:0 auto;border-radius:0}}

/* Logo + judul */
.brand{position:relative;display:flex;align-items:center;justify-content:center;gap:14px;padding:16px 28px;text-align:center}
.brand img{width:46px;height:auto;flex:none;display:block}
.brand .site-title{margin:0;font:700 27px/1.1 'Playfair Display',serif;letter-spacing:.5px}
.brand p{margin:2px 0 0;color:#7b8089;font-size:13px}

/* Header 2 kolom: kiri post, kanan merchandise */
.hero{display:grid;grid-template-columns:1.75fr 1fr;gap:0}
@media(max-width:720px){.hero{grid-template-columns:1fr}}
/* Slideshow header */
.slider{position:relative;height:280px;background:linear-gradient(135deg,#c9cdd3,#9aa0a9);overflow:hidden}
.slide{position:absolute;inset:0;display:block;cursor:pointer;opacity:0;visibility:hidden;pointer-events:none;transition:opacity 1.4s ease,visibility 1.4s}
.slide.on{opacity:1;visibility:visible;pointer-events:auto;z-index:1}
.slide .bg{position:absolute;inset:0;background:center/cover no-repeat;transform:scale(1.07);transition:transform 7s ease-out}
.slide.on .bg{transform:scale(1)}
.slide .cap{position:absolute;left:0;right:0;bottom:0;padding:50px 24px 22px;color:#fff;
  background:linear-gradient(transparent,rgba(30,33,38,.78))}
.cap small{font-size:11px;letter-spacing:2px;text-transform:uppercase;opacity:.85}
.cap .ct{display:block;margin:4px 0 0;font:600 21px/1.3 'Playfair Display',serif}
.merch .bg{background-size:cover;background-position:center}
.merch .slide{cursor:default}
.dots{position:absolute;right:22px;bottom:20px;z-index:3;display:flex;gap:7px;pointer-events:none}
.dots button{pointer-events:auto;width:8px;height:8px;padding:0;border:0;border-radius:8px;background:rgba(255,255,255,.5);cursor:pointer;transition:all .4s}
.dots button.on{width:24px;background:#fff}

/* Menu */
.nav{position:relative;background:#2f3237;z-index:10}
.nav-list,.sub{list-style:none;margin:0;padding:0}
.nav-list{display:flex;justify-content:center;padding:0 14px}
.nav-list li{position:relative}
.nav a{display:block;text-align:center;padding:14px 18px;color:#e9ebee;font-size:12.5px;letter-spacing:1.5px;text-transform:uppercase;transition:background .25s}
.nav a:hover{background:rgba(255,255,255,.08)}
.nav a.passive{cursor:default}
.nav-list>li>a{position:relative;transition:background .25s,transform .25s,letter-spacing .3s}
.nav-list>li>a::after{content:'';position:absolute;left:50%;bottom:8px;width:0;height:2px;background:#fff;transform:translateX(-50%);transition:width .35s ease}
.nav-list>li:hover>a{transform:translateY(-2px);letter-spacing:2px}
.nav-list>li:hover>a::after{width:46%}
@keyframes drop{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.sub{display:none;position:absolute;top:100%;left:50%;margin-left:-95px;min-width:190px;background:#3a3e44;box-shadow:0 10px 24px rgba(0,0,0,.2)}
.nav-list li:hover>.sub,.nav-list li:focus-within>.sub,.nav-list li.open>.sub{display:block;animation:drop .3s ease}
.nav .arr{display:inline-block;margin-left:4px;transition:transform .3s ease}
.nav-list li.open>a .arr{transform:rotate(180deg)}
.nav-toggle{display:none;position:absolute;right:16px;top:50%;margin-top:-21px;width:42px;height:42px;border:1px solid #c3c7cd;border-radius:10px;background:rgba(255,255,255,.7);color:#2f3237;font-size:20px;line-height:1;cursor:pointer;transition:background .25s}
.nav-toggle:hover{background:#fff}
@media(max-width:720px){
  .nav-toggle{display:block}
  .nav{display:none;position:absolute;left:0;right:0;z-index:50;box-shadow:0 14px 28px rgba(0,0,0,.25)}
  .nav.open{display:block;animation:drop .3s ease}
  .nav-list{flex-direction:column;padding:6px 0}
  .sub{display:none;position:static;margin-left:0;background:rgba(0,0,0,.18);box-shadow:none}
  .nav-list li:hover>.sub,.nav-list li:focus-within>.sub{display:none;animation:none}
  .nav-list li.open>.sub{display:block;animation:drop .3s ease}
  .nav a.passive{cursor:pointer}
  .nav-list>li:hover>a{transform:none;letter-spacing:1.5px}
  .nav-list>li>a::after{display:none}
  .sub a{padding-left:18px}
  .slider{height:190px}
  .cap .ct{font-size:16px}
}

/* Konten */
.content{padding:28px}
.page-head{margin:0 0 18px;font:700 22px 'Playfair Display',serif}
.page-head span{color:#7b8089}

/* Slideshow kalimat pembuka (beranda): tanpa latar, hanya animasi opacity + transform (ringan, tanpa JS) */
.intro{position:relative;margin:0 0 12px;padding:30px 12px 44px;text-align:center;contain:layout paint}
.intro-stage{display:grid}
.intro-slide{grid-area:1/1;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:8px;
  margin:0 auto;max-width:760px;opacity:0;font:600 22px/1.6 'Playfair Display',serif;color:#2f3237;
  animation:introSlide 16s cubic-bezier(.45,0,.25,1) infinite;will-change:opacity,transform}
.intro-slide.s2{animation-delay:8s;font-size:18px}
.intro-slide span{display:block}
.intro-slide.s1 span+span{color:#5d626b;opacity:0;animation:introSlide 16s cubic-bezier(.45,0,.25,1) .7s infinite;will-change:opacity,transform}
.intro-dots{position:absolute;left:0;right:0;bottom:16px;display:flex;justify-content:center;gap:8px}
.intro-dots i{width:8px;height:8px;border-radius:50%;background:#2f3237;opacity:.2;animation:introDot 16s linear infinite}
.intro-dots i+i{animation-delay:8s}
@keyframes introSlide{
  0%{opacity:0;transform:translate3d(0,14px,0)}
  7%{opacity:1;transform:translate3d(0,0,0)}
  46%{opacity:1;transform:translate3d(0,0,0)}
  54%{opacity:0;transform:translate3d(0,-10px,0)}
  100%{opacity:0;transform:translate3d(0,-10px,0)}
}
@keyframes introDot{0%{opacity:1}48%{opacity:1}52%{opacity:.2}100%{opacity:.2}}
@media(max-width:540px){.intro{padding:22px 4px 40px}.intro-slide{font-size:18px}.intro-slide.s2{font-size:15.5px}}
@media(prefers-reduced-motion:reduce){
  .intro-stage{display:block}
  .intro-slide,.intro-slide.s1 span+span,.intro-dots i{animation:none!important;opacity:1;transform:none;will-change:auto}
  .intro-slide+.intro-slide{margin-top:20px}
  .intro-dots{display:none}
}

/* Grid 3 kolom x 2 baris (6 post per halaman) */
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
@media(max-width:860px){.grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:540px){.grid{grid-template-columns:1fr}.content{padding:18px}}
.card{display:flex;flex-direction:column;background:#fff;border-radius:14px;overflow:hidden;
  box-shadow:0 4px 18px rgba(60,66,77,.08);transition:transform .3s,box-shadow .3s}
.card:hover{transform:translateY(-4px);box-shadow:0 12px 28px rgba(60,66,77,.15)}
.thumb{display:block;height:150px;overflow:hidden;background:linear-gradient(135deg,#dcdfe3,#b9bec6)}
.thumb img{width:100%;height:100%;object-fit:cover;transition:transform .5s}
.card:hover .thumb img{transform:scale(1.06)}
.card-body{display:flex;flex-direction:column;flex:1;padding:16px}
.tag{font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#8a8f98}
.card h2{margin:6px 0;font:600 17px/1.35 'Playfair Display',serif}
.card p{margin:0 0 14px;color:#5d626b;font-size:13.5px;line-height:1.6;
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.more,.btn{display:inline-block;padding:9px 18px;border-radius:999px;background:#2f3237;color:#fff;
  font-size:12px;letter-spacing:1px;transition:background .25s,transform .25s}
.more{margin-top:auto;align-self:flex-start}
.more:hover,.btn:hover{background:#5a5f68;transform:translateY(-1px)}

.card:has(.is-about){display:none}
/* Post lengkap */
.post-title{margin:0 0 6px;font:700 32px/1.25 'Playfair Display',serif}
.post-meta{margin-bottom:22px;color:#8a8f98;font-size:13px}
.post-meta a{margin-left:6px;padding:2px 10px;border-radius:99px;background:#e6e8eb;font-size:12px}
.post-body{font-size:16px;line-height:1.85}
.post-body img{height:auto;border-radius:10px}

.post-full.about .post-body img{filter:grayscale(1) contrast(1.06) brightness(1.03);box-shadow:0 8px 24px rgba(60,66,77,.18);transition:filter .5s}
/* Next / Last post */
.pager{display:flex;justify-content:space-between;gap:12px;margin:34px 0 10px}
.pager .next{margin-left:auto}
.comments{margin-top:30px}
.lblpager:empty{display:none}
/* Back to top */
.totop{position:fixed;right:20px;bottom:20px;z-index:60;display:grid;place-items:center;width:44px;height:44px;border-radius:50%;
  background:#2f3237;color:#fff;font-size:20px;line-height:1;box-shadow:0 8px 20px rgba(0,0,0,.25);
  opacity:0;visibility:hidden;transform:translateY(10px);transition:opacity .35s,transform .35s,visibility .35s,background .25s}
.totop.show{opacity:1;visibility:visible;transform:none}
.totop:hover{background:#5a5f68;transform:translateY(-3px)}

/* Footer 4 kolom (dirender saat mendekati layar = lebih ringan) */
.footer{text-align:center;background:#2f3237;color:#c9ccd2;padding:34px 28px 16px;content-visibility:auto;contain-intrinsic-size:auto 420px}
.foot-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:26px}
@media(max-width:860px){.foot-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:540px){.foot-grid{grid-template-columns:1fr}}
.footer h3{margin:0 0 12px;color:#fff;font:600 14px 'Playfair Display',serif;letter-spacing:1px}
.footer p{margin:0;font-size:13px;line-height:1.7}
/* Widget 1 (Tentang Aku): judul tetap di tengah, isi teks rata kiri */
#foot1 p{text-align:left}
.social{display:flex;justify-content:center;gap:10px}
.social a{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;border:1px solid #5a5f68;transition:all .25s}
.social a:hover{background:#fff;color:#2f3237}
.social svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.cloud{display:flex;flex-wrap:wrap;justify-content:center;gap:6px}
.cloud a{padding:3px 11px;border-radius:99px;background:#43474e;font-size:12px;transition:background .25s}
.cloud a:hover{background:#6a6f78}
.counts{list-style:none;margin:14px 0 0;padding:0}
.counts li{padding:5px 0;border-bottom:1px dashed #43474e;font-size:13px}
.counts a:hover{color:#fff}
.counts b{margin-left:6px;padding:1px 8px;border-radius:99px;background:#43474e;color:#fff;font-weight:500;font-size:11px}
.stat .num{display:block;color:#fff;font:700 34px/1.1 'Playfair Display',serif}
.stat span.lbl{font-size:12px;letter-spacing:1px;text-transform:uppercase}
.copy{margin-top:26px;padding-top:14px;border-top:1px solid #43474e;text-align:center;font-size:12px;color:#8e929a}

/* Aksesibilitas & performa: hormati pengaturan "kurangi gerakan" */
a:focus-visible,button:focus-visible{outline:2px solid #5a5f68;outline-offset:2px}
@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important}
  .slide .bg{transform:none}
}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
(function(){
  var d=document;
  var idle=window.requestIdleCallback||function(f){return setTimeout(f,300);};
  var reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;

  /* Sembunyikan kartu Tentang & Merchandise di grid */
  Array.prototype.forEach.call(d.querySelectorAll('.is-about'),function(e){var c=e.closest('.card');if(c)c.parentNode.removeChild(c);});

  var MERCH=['Merchandise','Jaket Hoodie','Kaos','Aksesoris'];
  function get(u){
    return fetch(u).then(function(r){return r.json();}).then(function(j){return (j.feed&&j.feed.entry)||[];}).catch(function(){return [];});
  }
  /* Ambil gambar dari feed ringkas lalu perkecil sesuai ukuran kolom (size) */
  function parse(x,ex,size){
    var cats=(x.category||[]).map(function(c){return c.term;});
    for(var k=0;k<ex.length;k++){if(cats.indexOf(ex[k])>-1)return null;}
    var m=/<img[^>]+src=["']([^"']+)["']/i.exec((x.content&&x.content.$t)||'');
    var img=m?m[1]:(x.media$thumbnail?x.media$thumbnail.url:'');
    if(!img)return null;
    if(/googleusercontent|bp\.blogspot/.test(img)){
      img=img.replace(/\/(?:s\d+|w\d+-h\d+)(?:-[a-z]+)?\//,'/'+size+'/').replace(/=(?:s\d+|w\d+-h\d+)(?:-[a-z]+)?$/,'='+size);
    }
    var l=x.link.filter(function(q){return q.rel==='alternate';})[0];
    return {title:x.title.$t,url:l?l.href:'/',img:img,pub:x.published?x.published.$t:''};
  }
  function slider(boxId,dotsId,url,tag,max,ex,size,fb,nolink){
    var box=d.getElementById(boxId),dots=d.getElementById(dotsId);
    if(!box)return;
    /* Ukuran gambar = pixel kolom sebenarnya x kerapatan layar (1.5x - 3x) agar tajam, tidak blur/pecah */
    var host=box.parentNode,dpr=Math.min(Math.max((window.devicePixelRatio||1)*1.15,1.5),3),cw=host.clientWidth,ch=host.clientHeight;
    if(cw&&ch)size='w'+Math.round(cw*dpr)+'-h'+Math.round(ch*dpr)+'-c';
    var cur=0,timer,list=[];
    /* Gambar slide hanya diunduh saat dibutuhkan (slide aktif + berikutnya) */
    function load(i){
      var s=box.children[i];
      if(s&&!s.getAttribute('data-l')&&list[i].img){s.setAttribute('data-l','1');s.firstChild.style.backgroundImage='url("'+list[i].img+'")';}
    }
    function show(n){
      var s=box.children,t=dots.children;
      if(!s.length)return;
      cur=(n+s.length)%s.length;
      load(cur);load((cur+1)%s.length);
      for(var i=0;i<s.length;i++){s[i].classList.toggle('on',i===cur);t[i].classList.toggle('on',i===cur);}
    }
    function stop(){clearInterval(timer);}
    function play(){stop();if(list.length>1&&!reduce&&!d.hidden)timer=setInterval(function(){show(cur+1);},5500);}
    function render(){
      list.forEach(function(it,i){
        var a=d.createElement(nolink?'div':'a');a.className='slide';if(!nolink)a.href=it.url;
        var bg=d.createElement('div');bg.className='bg';
        var cap=d.createElement('div');cap.className='cap';
        var sm=d.createElement('small');sm.textContent=tag;
        var h=d.createElement('strong');h.className='ct';h.textContent=it.title;
        cap.appendChild(sm);cap.appendChild(h);a.appendChild(bg);a.appendChild(cap);box.appendChild(a);
        var b=d.createElement('button');b.setAttribute('aria-label','Slide '+(i+1));
        b.onclick=function(){show(i);play();};dots.appendChild(b);
      });
      show(0);play();
    }
    get(url).then(function(res){
      var seen={},out=[];
      res.forEach(function(x){
        var it=parse(x,ex,size);
        if(it&&!seen[it.url]){seen[it.url]=1;out.push(it);}
      });
      out.sort(function(a,b){return a.pub<b.pub?1:-1;});
      list=out.slice(0,max);
      if(!list.length)list.push(fb);
      render();
    });
    d.addEventListener('visibilitychange',function(){if(d.hidden)stop();else play();});
  }
  /* Kolom kiri (624x280): post terbaru tanpa Tentang & Merchandise */
  slider('slides','dots','/feeds/posts/default?alt=json&max-results=15','Tulisan Terbaru',5,['Tentang'].concat(MERCH),'w624-h280-c',{title:d.title,url:'/',img:''});
  /* Kolom kanan (356x280): khusus Merchandise, gambar dipotong pas ukuran kolom, TANPA link (tidak bisa diklik) */
  slider('mslides','mdots','/feeds/posts/default/-/Merchandise?alt=json&max-results=6','Merchandise',6,['Tentang'],'w356-h280-c',{title:'Merchandise segera hadir',url:'/search/label/Merchandise',img:''},true);

  /* Menu Merchandise: tap untuk buka/tutup submenu (layar kecil & perangkat sentuh); desktop tetap hover */
  (function(){
    var btn=d.getElementById('merchBtn');
    if(!btn)return;
    var li=btn.parentNode,mq=window.matchMedia('(max-width:720px),(hover:none)');
    function set(o){li.classList.toggle('open',o);btn.setAttribute('aria-expanded',o?'true':'false');}
    btn.addEventListener('click',function(e){
      e.preventDefault();
      if(mq.matches)set(!li.classList.contains('open'));
    });
    btn.addEventListener('keydown',function(e){
      if(e.key==='Enter'||e.key===' '){e.preventDefault();set(!li.classList.contains('open'));}
      else if(e.key==='Escape')set(false);
    });
    /* Tutup bila tap di luar menu */
    d.addEventListener('click',function(e){if(!li.contains(e.target))set(false);});
    /* Reset saat ukuran layar berubah */
    window.addEventListener('resize',function(){if(!mq.matches)set(false);});
  })();

  /* Pekerjaan non-kritis dijalankan setelah halaman tampil */
  idle(function(){
    var t=d.getElementById('totalPost');
    if(t){
      fetch('/feeds/posts/summary?alt=json&max-results=0').then(function(r){return r.json();})
        .then(function(j){t.textContent=j.feed.openSearch$totalResults.$t;}).catch(function(){});
    }

    /* Last / Next Post: hanya Cerita & Renungan, berpindah dalam label yang sama */
    var lp=d.querySelector('.lblpager');
    if(lp){
      var lab=lp.getAttribute('data-label');
      fetch('/feeds/posts/summary/-/'+encodeURIComponent(lab)+'?alt=json&max-results=500')
        .then(function(r){return r.json();})
        .then(function(j){
          var e=(j.feed&&j.feed.entry)||[],here=location.pathname,idx=-1,urls=[];
          e.forEach(function(x,i){
            var l=x.link.filter(function(q){return q.rel==='alternate';})[0];
            var u=l?l.href:'';urls.push(u);
            try{if(new URL(u).pathname===here)idx=i;}catch(err){}
          });
          if(idx<0)return;
          function btn(cls,txt,u){var a=d.createElement('a');a.className='btn '+cls;a.href=u;a.textContent=txt;lp.appendChild(a);}
          if(idx+1<urls.length)btn('last','← Last Post',urls[idx+1]);
          if(idx>0)btn('next','Next Post →',urls[idx-1]);
        }).catch(function(){});
    }
  });

  /* Post Tentang: tandai agar gambarnya berwarna abu-abu senada website */
  Array.prototype.forEach.call(d.querySelectorAll('.post-full'),function(a){
    var tags=a.querySelectorAll('.post-meta a');
    for(var i=0;i<tags.length;i++){if(tags[i].textContent.replace(/\s+/g,' ').trim()==='Tentang'){a.classList.add('about');break;}}
  });

  /* Back to top (listener pasif + dibatasi per frame) */
  var tt=d.getElementById('toTop');
  if(tt){
    var tick=false;
    window.addEventListener('scroll',function(){
      if(tick)return;tick=true;
      requestAnimationFrame(function(){tt.classList.toggle('show',(window.pageYOffset||d.documentElement.scrollTop)>300);tick=false;});
    },{passive:true});
    tt.addEventListener('click',function(ev){ev.preventDefault();window.scrollTo({top:0,behavior:reduce?'auto':'smooth'});});
  }
})();
